CREATE OR REPLACE FUNCTION private.ai_turn_sweep_v5(p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_cutoff timestamptz := coalesce(p_at, statement_timestamp()) - interval '10 minutes';
  v_need integer := 0; v_worker integer := 0; v_qa integer := 0; v_review integer := 0; v_errors jsonb := '[]'::jsonb;
begin
  -- A turn whose lease ended ten minutes ago will never be completed by the worker that claimed it.
  -- Expiry is still not proof that the provider did not run, so the request itself is never retried:
  -- it stays failed, and only a NEW request from the person can continue the conversation. What changes
  -- is that it stops blocking that conversation and the account's closure forever.
  begin
    update private.ai_need_turn_commands set state = 'FAILED', updated_at = clock_timestamp()
     where state = 'PROCESSING' and lease_expires_at < v_cutoff;
    get diagnostics v_need = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'NEED_INTAKE', 'sqlstate', sqlstate));
  end;
  begin
    update private.worker_ai_turns set state = 'FAILED'
     where state = 'PROCESSING' and lease_expires_at < v_cutoff;
    get diagnostics v_worker = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'WORKER_PROFILE', 'sqlstate', sqlstate));
  end;
  begin
    -- CANCELLED is the existing "this send will never publish anything" state the app already explains.
    update private.qa_ai_commands set state = 'CANCELLED', updated_at = clock_timestamp()
     where state = 'PROCESSING' and lease_expires_at < v_cutoff
       and not private.closure_account_restricted(account_id);
    get diagnostics v_qa = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'PRESELECTION_QA', 'sqlstate', sqlstate));
  end;
  -- PKG-037: a publication claim cannot complete after its 60-second lease.
  -- End expired attempts without a decision, another paid request or any refund.
  -- Lock only a bounded batch; an in-flight completion wins or is fenced by state.
  begin
    with expired as (
      select c.review_id from private.ai_task_review_commands c
       where c.state = 'EVALUATING'
         and c.lease_expires_at <= least(coalesce(p_at, statement_timestamp()), clock_timestamp())
       order by c.lease_expires_at, c.review_id limit 100 for update skip locked
    )
    update private.ai_task_review_commands c set state = 'EVALUATED',
      evaluation = jsonb_build_object('kind','NOT_READY','needId',c.need_id,
        'needRevision',c.need_revision,'authoritativeDecision',false,'code','EVALUATOR_UNAVAILABLE'),
      evaluation_result_hash = encode(extensions.digest(jsonb_build_object(
        'outcome',null,'rules','[]'::jsonb,'reasons','[]'::jsonb,'provider',null,'model',null,
        'notReady','EVALUATOR_UNAVAILABLE')::text,'sha256'),'hex')
     where c.review_id in (select review_id from expired) and c.state = 'EVALUATING';
    get diagnostics v_review = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns','PUBLICATION_REVIEW','sqlstate',sqlstate));
  end;
  return jsonb_build_object('needTurnsFailed', v_need, 'workerTurnsFailed', v_worker,
    'qaCommandsCancelled', v_qa, 'reviewEvaluationsStopped', v_review, 'graceMinutes', 10, 'errors', v_errors);
end
$function$

CREATE OR REPLACE FUNCTION private.claim_retention_job(p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare b jsonb;candidate record;c public.ai_conversations;v jsonb;j private.retention_jobs;now_at timestamptz;due timestamptz;token uuid;
 scan private.retention_scan_cursors;scope uuid:=coalesce(p_account_id,'00000000-0000-0000-0000-000000000000'::uuid);
begin
 lock table private.retention_policy_sets,private.retention_policy_rules,private.retention_data_classes,private.legal_document_versions in share mode;
 b:=private.retention_execution_binding();if b is null then return jsonb_build_object('kind','NOT_READY','code','POLICY_NOT_READY');end if;
 if not coalesce(private.retention_ai_source_ready(),false) then return jsonb_build_object('kind','NOT_READY','code','SOURCE_NOT_READY');end if;
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:retention-scan:'||scope::text,0)) then return jsonb_build_object('kind','NONE');end if;
 insert into private.retention_scan_cursors(scope_id) values(scope) on conflict do nothing;
 select * into scan from private.retention_scan_cursors where scope_id=scope for update;
 now_at:=clock_timestamp();
 if scan.abandoned_at is not null and not exists(select 1 from public.ai_conversations c0 where c0.status='ABANDONED' and c0.retention_unbound_origin
  and c0.retention_abandoned_at is not null and (p_account_id is null or c0.account_id=p_account_id)
  and (c0.retention_abandoned_at,c0.id)>(scan.abandoned_at,scan.conversation_id)
  and c0.retention_abandoned_at<=now_at-make_interval(secs=>(b->>'retentionSeconds')::integer)) then
  scan.abandoned_at:=null;scan.conversation_id:=null;
 end if;
 for candidate in select c0.id,c0.account_id,c0.retention_abandoned_at from public.ai_conversations c0 where c0.status='ABANDONED' and c0.retention_unbound_origin and c0.retention_abandoned_at is not null
 and (p_account_id is null or c0.account_id=p_account_id) and c0.retention_abandoned_at<=now_at-make_interval(secs=>(b->>'retentionSeconds')::integer)
 and (scan.abandoned_at is null or (c0.retention_abandoned_at,c0.id)>(scan.abandoned_at,scan.conversation_id))
 order by c0.retention_abandoned_at,c0.id limit 100 loop
   update private.retention_scan_cursors set abandoned_at=candidate.retention_abandoned_at,conversation_id=candidate.id where scope_id=scope;
   -- Closure always precedes retention and parent locks. Busy/restricted accounts
   -- are skipped; no new CLAIMED row can deadlock its closure guard.
   if not pg_try_advisory_xact_lock_shared(private.closure_account_key(candidate.account_id)) then continue;end if;
   if private.closure_account_restricted(candidate.account_id) then continue;end if;
   if not pg_try_advisory_xact_lock(hashtextextended('uskoci:retention:'||candidate.account_id::text,0)) then continue;end if;
   select * into c from public.ai_conversations where id=candidate.id for update skip locked;if not found then continue;end if;
   now_at:=clock_timestamp();v:=private.retention_ai_candidate(c.id);if v is null then continue;end if;
   due:=(v->>'abandonedAt')::timestamptz+make_interval(secs=>(b->>'retentionSeconds')::integer);if due>now_at then continue;end if;
   if exists(select 1 from private.retention_holds where account_id=c.account_id and active and (conversation_id is null or conversation_id=c.id)) then continue;end if;
   select * into j from private.retention_jobs where conversation_id=c.id for update;
   if found and (j.status='SUCCEEDED' or j.attempt_number>=5 or (j.status='CLAIMED' and j.lease_until>now_at) or j.next_attempt_at>now_at) then continue;end if;
   token:=gen_random_uuid();
   insert into private.retention_jobs(account_id,conversation_id,status,attempt_id,attempt_number,lease_until,policy_id,policy_sha256,source_sha256,due_at)
   values(c.account_id,c.id,'CLAIMED',token,1,now_at+interval '120 seconds',(b->>'policyId')::uuid,b->>'sha256',v->>'sha256',due)
   on conflict(conversation_id) do update set status='CLAIMED',attempt_id=excluded.attempt_id,attempt_number=retention_jobs.attempt_number+1,
    lease_until=excluded.lease_until,policy_id=excluded.policy_id,policy_sha256=excluded.policy_sha256,source_sha256=excluded.source_sha256,due_at=excluded.due_at,
    next_attempt_at=null,last_code=null,result=null,updated_at=now_at returning * into j;
   perform private.audit_marketplace(null,'RETENTION_JOB_CLAIMED','SYSTEM',j.id,null,jsonb_build_object('attempt',j.attempt_number,'policyId',j.policy_id,'dataset',j.dataset));
   return jsonb_build_object('kind','CLAIMED','jobId',j.id,'attemptId',j.attempt_id,'leaseExpiresAt',j.lease_until,'dataset',j.dataset,'policyVersion',b->>'policyVersion');
 end loop;
 return jsonb_build_object('kind','NONE');
end $function$

CREATE OR REPLACE FUNCTION private.data_export_maintenance(p_batch integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare candidate record; r public.data_export_requests; v_now timestamptz; purged integer:=0; expired integer:=0; n integer;
begin
 for candidate in select d.id,d.account_id from public.data_export_requests d where exists(select 1 from private.data_export_artifacts a where a.receipt_id=d.id and ((a.snapshot_text is not null and a.snapshot_expires_at<=clock_timestamp()) or (a.id=d.active_export_attempt_id and d.status='READY' and a.artifact_expires_at<=clock_timestamp()))) order by d.id limit greatest(1,least(coalesce(p_batch,25),100)) loop
   if not pg_try_advisory_xact_lock(hashtextextended('uskoci:data-export:'||candidate.account_id::text,0)) then continue; end if;
   select * into r from public.data_export_requests where id=candidate.id for update skip locked;if not found then continue;end if;v_now:=clock_timestamp();
   update private.data_export_artifacts set snapshot_text=null where receipt_id=r.id and snapshot_text is not null and snapshot_expires_at<=v_now and (lease_until<=v_now or verified_at is not null);
   get diagnostics n=row_count;purged:=purged+n;
   if r.status='READY' and exists(select 1 from private.data_export_artifacts where id=r.active_export_attempt_id and artifact_expires_at<=v_now) then
     update public.data_export_requests set status='EXPIRED',updated_at=v_now where id=r.id;
     update private.data_export_artifacts set download_grant_id=null,download_grant_expires_at=null where id=r.active_export_attempt_id;
     perform private.audit_marketplace(r.account_id,'DATA_EXPORT_EXPIRED','SYSTEM',r.id,null,'{}'::jsonb);expired:=expired+1;
   end if;
 end loop;
 return jsonb_build_object('expiredRequests',expired,'temporarySnapshotsPurged',purged,'storageWorkerRequired',true,'storageDeletionPerformed',false);
end $function$

CREATE OR REPLACE FUNCTION private.execute_retention_job(p_job_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j private.retention_jobs;b jsonb;v jsonb;now_at timestamptz;code text;v_result jsonb;message_count integer:=0;account uuid;
begin
 lock table private.retention_policy_sets,private.retention_policy_rules,private.retention_data_classes,private.legal_document_versions in share mode;
 select account_id into account from private.retention_jobs where id=p_job_id;if not found then raise exception 'RETENTION_JOB_NOT_FOUND';end if;
 -- Preserve immutable result replay; acquire the shared closure fence first.
 perform pg_advisory_xact_lock_shared(private.closure_account_key(account));
 perform pg_advisory_xact_lock(hashtextextended('uskoci:retention:'||account::text,0));
 select * into j from private.retention_jobs where id=p_job_id for update;
 if p_attempt_id is null or j.attempt_id<>p_attempt_id then raise exception 'RETENTION_ATTEMPT_STALE' using errcode='PT409';end if;
 if j.result is not null then return j.result||jsonb_build_object('idempotentReplay',true);end if;
 perform 1 from public.ai_conversations where id=j.conversation_id for update;
 now_at:=clock_timestamp();b:=private.retention_execution_binding();v:=private.retention_ai_candidate(j.conversation_id);
 code:=case when j.lease_until<=now_at then 'LEASE_EXPIRED'
   when exists(select 1 from private.retention_holds where account_id=j.account_id and active and (conversation_id is null or conversation_id=j.conversation_id)) then 'HELD'
   when b is null or b->>'sha256'<>j.policy_sha256 then 'POLICY_CHANGED'
   when not coalesce(private.retention_ai_source_ready(),false) or v is null or v->>'sha256'<>j.source_sha256 or j.due_at>now_at then 'SOURCE_CHANGED' else null end;
 if code is null then
   begin
     -- No network or Storage work: final hold check and complete deletion commit
     -- atomically under the account+parent locks. The candidate has no facts,
     -- proposals, draft receipts or links to Need/edit evidence.
     message_count:=(v->>'messageCount')::integer;
     delete from public.ai_conversations where id=j.conversation_id;
     if not found then raise exception 'RETENTION_SOURCE_DISAPPEARED';end if;
     v_result:=jsonb_build_object('jobId',j.id,'status','SUCCEEDED','deletedConversation',true,'deletedMessages',message_count,'idempotentReplay',false);
     update private.retention_jobs set status='SUCCEEDED',result=v_result,last_code=null,next_attempt_at=null,updated_at=clock_timestamp() where id=j.id;
     perform private.audit_marketplace(null,'RETENTION_DELETE_COMPLETED','SYSTEM',j.id,null,jsonb_build_object('dataset',j.dataset,'policyId',j.policy_id,'deletedMessages',message_count));
     return v_result;
   exception when others then
     -- Subtransaction rollback restores every deleted row before recording a
     -- bounded technical retry. Never expose exception text or private content.
     code:='EXECUTION_FAILED';
   end;
 end if;
 v_result:=jsonb_build_object('jobId',j.id,'status',case when code='EXECUTION_FAILED' then 'FAILED' else 'BLOCKED' end,
 'code',code,'deletedConversation',false,'deletedMessages',0,'idempotentReplay',false);
 update private.retention_jobs set status=case when code='EXECUTION_FAILED' then 'FAILED' else 'BLOCKED' end,last_code=code,result=v_result,
  next_attempt_at=case when attempt_number<5 then clock_timestamp()+interval '60 seconds' else null end,updated_at=clock_timestamp() where id=j.id;
 perform private.audit_marketplace(null,'RETENTION_DELETE_DEFERRED','SYSTEM',j.id,null,jsonb_build_object('code',code,'attempt',j.attempt_number));
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION private.expire_urgent(at_time timestamp with time zone DEFAULT statement_timestamp())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record; expired_count integer := 0;
begin
  for r in
    select id, revision from public.needs
     where urgent = true and urgent_expires_at is not null and urgent_expires_at <= at_time
     for update skip locked
  loop
    update public.needs set urgent = false where id = r.id;
    update public.dispatch_rounds set status='STOPPED', stop_reason='URGENT_EXPIRED'
     where need_id = r.id and need_revision = r.revision
       and urgency = 'URGENT' and status in ('PLANNED','SENT');
    expired_count := expired_count + 1;
  end loop;
  return expired_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.retention_maintenance(p_batch integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare i integer;j jsonb;r jsonb;deleted integer:=0;deferred integer:=0;
begin
 for i in 1..greatest(1,least(coalesce(p_batch,25),25)) loop
   j:=private.claim_retention_job();if j->>'kind'<>'CLAIMED' then
     return jsonb_build_object('deletedConversations',deleted,'deferred',deferred,'state',j->>'kind','code',j->>'code','storageCleanup','NOT_APPLICABLE');end if;
   r:=private.execute_retention_job((j->>'jobId')::uuid,(j->>'attemptId')::uuid);
   if r->>'status'='SUCCEEDED' then deleted:=deleted+1;else deferred:=deferred+1;end if;
 end loop;
 return jsonb_build_object('deletedConversations',deleted,'deferred',deferred,'state','BATCH_COMPLETED','storageCleanup','NOT_APPLICABLE');
end $function$

CREATE OR REPLACE FUNCTION private.sync_need_completion(p_need_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs;
  v_completed_slots integer := 0;
  v_active_selected_slots integer := 0;
  v_effective_required integer := 0;
begin
  select * into n
    from public.needs
   where id = p_need_id
   for update;

  if not found then
    return false;
  end if;

  if n.status = 'COMPLETED' then
    return true;
  end if;

  if n.status not in ('ACTIVE','SELECTION') then
    return false;
  end if;

  select coalesce(sum(s.covered_slots), 0)::integer
    into v_completed_slots
    from public.need_selections s
    join public.agreements a on a.selection_id = s.id
   where s.need_id = p_need_id
     and s.status = 'SELECTED'
     and a.status = 'COMPLETED';

  -- When remaining search was explicitly closed, evaluate against active selected slots
  if n.remaining_search_closed_at is not null then
    select coalesce(sum(s.covered_slots), 0)::integer
      into v_active_selected_slots
      from public.need_selections s
     where s.need_id = p_need_id
       and s.status = 'SELECTED';
    v_effective_required := v_active_selected_slots;
  else
    v_effective_required := n.required_slots;
  end if;

  if v_effective_required < 1 or v_completed_slots < v_effective_required then
    return false;
  end if;

  perform set_config('uskoci.need_lifecycle', 'COMPLETE', true);

  update public.needs
     set status = 'COMPLETED',
         updated_at = statement_timestamp()
   where id = p_need_id
     and status in ('ACTIVE','SELECTION');

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_tick_auto_completion()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare candidate record; a public.agreements; x public.agreement_execution; done integer:=0; at_time timestamptz:=statement_timestamp();
begin
 for candidate in select ag.id,ag.need_id from public.agreements ag join public.agreement_execution ex on ex.agreement_id=ag.id
   where ag.status='CONFIRMED' and ex.state='AWAITING_REQUESTER' and ex.problem_opened_at is null
     and ex.requester_deadline_at is not null and ex.requester_deadline_at<=at_time
   order by ag.need_id,ag.id limit 100
 loop
   perform 1 from public.needs where id=candidate.need_id for update skip locked;
   if not found then continue; end if;
   select * into a from public.agreements where id=candidate.id for update skip locked;
   if not found or a.status<>'CONFIRMED' then continue; end if;
   select * into x from public.agreement_execution where agreement_id=a.id for update skip locked;
   if not found or x.state<>'AWAITING_REQUESTER' or x.agreement_version<>a.current_version
     or x.problem_opened_at is not null or x.requester_deadline_at is null or x.requester_deadline_at>at_time
     or exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then continue; end if;
   update public.agreement_execution set state='COMPLETED',completed_at=at_time,requester_deadline_at=null,updated_at=at_time where agreement_id=a.id;
   update public.agreements set status='COMPLETED',updated_at=at_time where id=a.id;
   perform private.sync_need_completion(a.need_id);
   -- PKG-029a (deep read 1.2): the worker is told the job closed, exactly as when the requester confirms (same
   -- event, same dedupe key, so the two paths can never both notify).
   perform private.emit_event(a.worker_account_id, 'WORKER', 'EXECUTION_STATE_CHANGED', 'AGREEMENT', a.id, a.current_version,
     'Dogovor je završen', 'Rok za potvrdu je istekao, pa je završetak potvrđen automatski.',
     'completed:worker:' || a.id::text || ':' || a.current_version::text, 'NORMAL',
     jsonb_build_object('completedAt', at_time, 'automatic', true), null);
   done:=done+1;
 end loop;
 return done;
end;
$function$

CREATE OR REPLACE FUNCTION private.retention_execution_binding()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p private.retention_policy_sets;m jsonb;privacy private.legal_document_versions;rules jsonb;binding jsonb;
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=statement_timestamp();
 if not found or p.retention_execution is null then return null;end if;m:=p.retention_execution;
 if m-ARRAY['schemaVersion','adapterVersion','dataClass','dataset','action','trigger','retentionSeconds','privacyDocumentId','privacyContentSha256','contentSha256']<>'{}'::jsonb
 or not(m ?& ARRAY['schemaVersion','adapterVersion','dataClass','dataset','action','trigger','retentionSeconds','privacyDocumentId','privacyContentSha256','contentSha256'])
 or m->'schemaVersion' is distinct from '1'::jsonb or m->>'adapterVersion' is distinct from 'P3_AI_ABANDONED_UNBOUND_V1'
 or m->>'dataClass' is distinct from 'AI_VOLATILE' or m->>'dataset' is distinct from 'AI_ABANDONED_UNBOUND'
 or m->>'action' is distinct from 'DELETE' or m->>'trigger' is distinct from 'OBSERVED_ABANDONMENT'
 or jsonb_typeof(m->'retentionSeconds') is distinct from 'number' or (m->>'retentionSeconds')!~'^[1-9][0-9]{0,9}$'
 or coalesce(m->>'privacyDocumentId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[a-f0-9]{64}$' or coalesce(m->>'contentSha256','')!~'^[a-f0-9]{64}$'
 then return null;end if;
 if (m->>'retentionSeconds')::numeric>2147483647 then return null;end if;
 if encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex')<>m->>'contentSha256' then return null;end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY'
 and is_active and published_at<=statement_timestamp() and effective_at<=statement_timestamp() and content_sha256=m->>'privacyContentSha256';
 if not found or not exists(select 1 from private.retention_data_classes where code='AI_VOLATILE' and active and required)
 or exists(select 1 from private.retention_data_classes d where d.active and d.required and not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=d.code))
 then return null;end if;
 select jsonb_agg(to_jsonb(r) order by r.data_class) into rules from private.retention_policy_rules r where policy_id=p.id;
 binding:=jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'effectiveAt',p.effective_at,'counselReference',p.counsel_reference,
 'rules',rules,'execution',m,'privacy',jsonb_build_object('id',privacy.id,'contentSha256',privacy.content_sha256,'version',privacy.version_label));
 return jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'retentionSeconds',m->'retentionSeconds',
 'sha256',encode(extensions.digest(convert_to(binding::text,'UTF8'),'sha256'),'hex'));
end $function$

CREATE OR REPLACE FUNCTION private.after_need_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if new.revision>old.revision then
  for r in with affected as (
   update public.marketplace_responses set status='STALE_REVIEW_REQUIRED'
    where need_id=new.id and submitted_against_need_revision=old.revision
     and status in('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')
    returning id,worker_account_id,current_version)
   select distinct on(worker_account_id) * from affected order by worker_account_id,id
  loop
   -- Own Application is the safe target even while the revised Need is DRAFT.
   perform private.emit_event(r.worker_account_id,'WORKER','NEED_REVISED','RESPONSE',r.id,new.revision,
    'Zadatak je izmenjen','Pregledajte svoju prijavu pre nastavka.',
    'need-revised:'||new.id::text||':'||new.revision::text||':worker:'||r.worker_account_id::text,
    'NORMAL',jsonb_build_object('needId',new.id,'responseId',r.id,'fromRevision',old.revision,'needRevision',new.revision),null);
  end loop;
  update public.opportunity_deliveries set status='EXPIRED'
   where need_id=new.id and need_revision=old.revision and status in('READY','SEEN');
  update public.dispatch_rounds set status='STOPPED',stop_reason='NEED_REVISED'
   where need_id=new.id and need_revision=old.revision and status in('PLANNED','SENT');
  -- Never dispatch or auto-publish a newly revised DRAFT.
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enqueue_on_need_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.status in ('PUBLISHED','SELECTION') then
    if tg_op = 'INSERT'
       or old.status is distinct from new.status
       or old.revision is distinct from new.revision then
      perform private.enqueue_dispatch(new.id, statement_timestamp());
      -- Durable dispatch_schedule is serviced outside the publication transaction.
    end if;
  elsif tg_op = 'UPDATE' and old.status is distinct from new.status then
    delete from private.dispatch_schedule where need_id = new.id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_closed_remaining_search_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_closed timestamptz;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.status not in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','SELECTED') then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.status is not distinct from old.status
     and new.submitted_against_need_revision is not distinct from old.submitted_against_need_revision
     and new.current_version is not distinct from old.current_version then
    return new;
  end if;

  select n.remaining_search_closed_at into v_closed
    from public.needs n
   where n.id = new.need_id;

  if v_closed is not null then
    raise exception 'NEED_REMAINING_SEARCH_CLOSED' using errcode='P0001';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_need_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  token text := current_setting('uskoci.need_lifecycle', true);
  material boolean;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if (tg_op='INSERT' and (new.task_country_code is not null or new.task_timezone is not null))
    or (tg_op='UPDATE' and (new.task_country_code is distinct from old.task_country_code or new.task_timezone is distinct from old.task_timezone)) then
    if current_setting('uskoci.need_region',true) is distinct from 'CONFIRMED_REVIEW' then
      raise exception 'NEED_COUNTRY_REQUIRES_CONFIRMED_REVIEW' using errcode='42501';
    end if;
    perform private.require_location_country(to_jsonb(new.task_country_code));
    if new.task_timezone is distinct from (select default_timezone from private.location_market_configs where country_code=new.task_country_code) then
      raise exception 'NEED_COUNTRY_TIMEZONE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if not exists (
    select 1 from public.app_profiles p
     where p.id = new.requester_profile_id
       and p.account_id = new.requester_account_id
       and p.kind = 'REQUESTER'
  ) then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'DRAFT'
       and not (new.status = 'PUBLISHED' and token = 'PUBLISH') then
      raise exception using errcode='22023', message='NEED_MUST_START_AS_DRAFT';
    end if;
    if token is null then
      new.urgent := false;
      new.urgent_activated_at := null;
      new.urgent_expires_at := null;
      new.urgent_policy_version := null;
      new.published_at := null;
      new.response_deadline := null;
    end if;
    return new;
  end if;

  if old.status in ('COMPLETED','CANCELLED','EXPIRED','ARCHIVED')
     and (
       (to_jsonb(new) - array['urgent','updated_at'])
         is distinct from
       (to_jsonb(old) - array['urgent','updated_at'])
       or (not coalesce(old.urgent, false) and coalesce(new.urgent, false))
     ) then
    raise exception using errcode='22023', message='NEED_TERMINAL_IMMUTABLE';
  end if;

  if new.requester_account_id <> old.requester_account_id then
    raise exception using errcode='42501', message='NEED_OWNER_IMMUTABLE';
  end if;

  material :=
       new.task_country_code is distinct from old.task_country_code
    or new.task_timezone is distinct from old.task_timezone
    or
       new.title is distinct from old.title
    or new.description is distinct from old.description
    or new.category is distinct from old.category
    or new.required_slots is distinct from old.required_slots
    or new.mode is distinct from old.mode
    or new.requester_price_rsd is distinct from old.requester_price_rsd
    or new.required_skills is distinct from old.required_skills
    or new.required_tools is distinct from old.required_tools
    or new.required_vehicles is distinct from old.required_vehicles
    or new.required_licenses is distinct from old.required_licenses
    or new.minimum_experience_years is distinct from old.minimum_experience_years
    or new.verified_identity_required is distinct from old.verified_identity_required
    or new.schedule_kind is distinct from old.schedule_kind
    or new.starts_at is distinct from old.starts_at
    or new.ends_at is distinct from old.ends_at
    or new.execution_location_mode is distinct from old.execution_location_mode
    or new.approximate_lat is distinct from old.approximate_lat
    or new.approximate_lng is distinct from old.approximate_lng
    or new.approximate_city is distinct from old.approximate_city
    or new.approximate_area is distinct from old.approximate_area
    or new.public_photo_paths is distinct from old.public_photo_paths
    or new.response_deadline is distinct from old.response_deadline;

  if token = 'CONFIRM_EDIT' then
    if old.status not in ('DRAFT','PUBLISHED','SELECTION') or new.status <> 'DRAFT' then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_STATUS_INVALID';
    end if;
    if new.revision <> old.revision + 1 then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_REVISION_INVALID';
    end if;
    if exists (select 1 from public.agreements a where a.need_id = old.id)
       or exists (select 1 from public.need_selections s where s.need_id = old.id)
       or exists (select 1 from public.marketplace_responses r where r.need_id = old.id and r.status = 'SELECTED') then
      raise exception using errcode='P0001', message='NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR';
    end if;
    if new.published_at is not null or new.response_deadline is not null then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_PUBLICATION_METADATA_NOT_CLEARED';
    end if;
    if coalesce(new.urgent, false)
       or new.urgent_activated_at is not null
       or new.urgent_expires_at is not null
       or new.urgent_policy_version is not null then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_URGENT_METADATA_NOT_CLEARED';
    end if;
    return new;
  end if;

  -- R09: the publication/revision witness cannot be refreshed by an empty
  -- or unrelated lifecycle token. CONFIRM_EDIT and authorized closure return
  -- above; the only remaining publication writer is canonical DRAFT->PUBLISHED.
  if new.revision is distinct from old.revision then
    raise exception 'NEED_REVISION_IS_SERVER_OWNED' using errcode='42501';
  end if;
  if new.published_at is distinct from old.published_at
     and (token is distinct from 'PUBLISH' or old.status <> 'DRAFT' or new.status <> 'PUBLISHED') then
    raise exception 'PUBLISHED_AT_IS_SERVER_OWNED' using errcode='42501';
  end if;

  if new.status is distinct from old.status then
    if not (
         (token = 'PUBLISH' and old.status = 'DRAFT' and new.status = 'PUBLISHED')
      or (token = 'SELECT' and old.status in ('PUBLISHED','SELECTION') and new.status in ('SELECTION','ACTIVE'))
      or (token = 'CANCEL_NEED' and old.status in ('DRAFT','PUBLISHED','SELECTION') and new.status = 'CANCELLED')
      or (token = 'CANCEL_AGREEMENT' and old.status in ('ACTIVE','SELECTION') and new.status = 'SELECTION')
      or (token = 'EXPIRE' and old.status in ('PUBLISHED','SELECTION') and new.status = 'EXPIRED')
      or (token = 'COMPLETE' and old.status in ('ACTIVE','SELECTION') and new.status = 'COMPLETED')
    ) then
      raise exception using errcode='22023', message='NEED_STATUS_TRANSITION_REQUIRES_RPC';
    end if;
  end if;

  if token is null then
    if new.revision is distinct from old.revision then
      raise exception using errcode='42501', message='NEED_REVISION_IS_SERVER_OWNED';
    end if;
    if new.urgent is distinct from old.urgent then raise exception using errcode='42501', message='URGENT_IS_SERVER_OWNED'; end if;
    if new.urgent_activated_at is distinct from old.urgent_activated_at then raise exception using errcode='42501', message='URGENT_ACTIVATED_AT_IS_SERVER_OWNED'; end if;
    if new.urgent_expires_at is distinct from old.urgent_expires_at then raise exception using errcode='42501', message='URGENT_EXPIRES_AT_IS_SERVER_OWNED'; end if;
    if new.urgent_policy_version is distinct from old.urgent_policy_version then raise exception using errcode='42501', message='URGENT_POLICY_VERSION_IS_SERVER_OWNED'; end if;
    if new.published_at is distinct from old.published_at then raise exception using errcode='42501', message='PUBLISHED_AT_IS_SERVER_OWNED'; end if;
    if new.response_deadline is distinct from old.response_deadline then raise exception using errcode='42501', message='RESPONSE_DEADLINE_IS_SERVER_OWNED'; end if;
  end if;

  if material then
    if old.status in ('PUBLISHED','SELECTION') then
      raise exception using errcode='22023', message='PUBLIC_NEED_EDIT_REQUIRES_CONFIRM_COMMAND';
    elsif old.status <> 'DRAFT' then
      raise exception using errcode='P0001', message='NEED_NOT_EDITABLE';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_urgent_need()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare token text := current_setting('uskoci.urgent_activation_need', true);
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if tg_op = 'INSERT' and new.urgent then
    raise exception using errcode='22023', message='URGENT_ACTIVATION_RPC_REQUIRED';
  end if;
  if tg_op = 'UPDATE' and not coalesce(old.urgent,false) and new.urgent then
    if token is distinct from new.id::text then
      raise exception using errcode='22023', message='URGENT_ACTIVATION_RPC_REQUIRED';
    end if;
    if new.urgent_activated_at is null or new.urgent_expires_at is null
       or new.urgent_expires_at <= new.urgent_activated_at
       or nullif(btrim(coalesce(new.urgent_policy_version,'')),'') is null then
      raise exception using errcode='22023', message='URGENT_ACTIVATION_METADATA_INVALID';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  new.updated_at := statement_timestamp();
